const { logger: { l }, timer } = require('../helper')
const COLOR = ['green', 'cyan', 'red', 'whiteBright']

const _cliProgress = require('cli-progress')
const bar = new _cliProgress.Bar({}, _cliProgress.Presets.shades_classic)


timer.begin('exe')

var longestCycle = function (edges) {
  let edgesFT = edges.map((e, i) => ({ from: i, to: e })).filter(e => e.to > -1)
  let removed = true
  while (removed) {
    const startLength = edgesFT.length
    const startNodes = new Set(edgesFT.map(e => e.to))
    edgesFT = edgesFT.filter(({ from, to }) => startNodes.has(from))
    removed = edgesFT.length < startLength
  }
  // console.log(edgesFT)
  l`{${COLOR[2]} removed redundant edges: ${timer.point('exe')}} seconds.`
  const groups = []
  edgesFT.forEach(({ from, to }) => {
    const containGroup1 = groups.find(g => g.has(from) || g.has(to))
    if (containGroup1) {
      const containGroup2 = containGroup1 && groups.find(g => g !== containGroup1 && (g.has(from) || g.has(to)))
      try {
        if (containGroup2) [...containGroup2].forEach(e => {
          containGroup1.add(e)
          containGroup2.delete(e)
        })
      } catch (error) {
        console.log(containGroup2)
        throw error
      }
      containGroup1.add(from).add(to)
    }
    else groups.push(new Set([from, to]))
  })

  l`{${COLOR[2]} grouped: ${timer.point('exe')}} seconds.`
  console.log('groups length' + groups.length)
  return Math.max(-1, ...groups.map(e => e.size))
}

